  "command": "cat > /workspace/dev_tests/analyze.py <<'PYEOF'
import json, sys, statistics

def pearson(xs, ys):
    n = len(xs)
    if n < 2: return None
    mx = sum(xs)/n; my = sum(ys)/n
    num = sum((x-mx)*(y-my) for x,y in zip(xs,ys))
    dx = sum((x-mx)**2 for x in xs)**0.5
    dy = sum((y-my)**2 for y in ys)**0.5
    if dx == 0 or dy == 0: return 0.0
    return num/(dx*dy)

def load_domain_scores(results):
    # results: dict model -> list of items (from result.json)
    out = {}
    for m, items in results.items():
        dom = {}
        for it in items:
            qid = it.get('question_id') or it['id']
            d = qid.split('_')[1]
            sc = it.get('score')
            if sc is None: sc = 0.0
            dom.setdefault(d, []).append(sc)
        out[m] = {d: statistics.mean(v) for d,v in dom.items()}
    return out

def main(results_files):
    # results_files: list of (model, path)
    results = {}
    for m, p in results_files:
        d = json.load(open(p))
        results[m] = d['result']['items']
    dscores = load_domain_scores(results)
    print('=== domain scores per model ===')
    for m in sorted(dscores):
        print(f'{m}: ' + '  '.join(f'{k}={v:.3f}' for k,v in sorted(dscores[m].items())))
    wb = json.load(open('/workspace/whitebox.json'))
    targets = wb['targets']
    domains = wb['domains']
    # per-target pearson
    per_target = {}
    for name, spec in targets.items():
        dom = spec['domain']
        ref = spec['scores']
        xs, ys = [], []
        for m, v in ref.items():
            if m in dscores and dom in dscores[m]:
                xs.append(dscores[m][dom])
                ys.append(v)
        r = pearson(xs, ys) if len(xs) >= 2 else None
        per_target[name] = r
        print(f'target {name:24s} [{dom:8s}]: n={len(xs)} pearson={"%.3f"%r if r is not None else "NA"}  (my={xs} ref={ys})')
    # aggregate by domain
    dom_avg = {}
    for dom, tlist in domains.items():
        rs = [per_target[t] for t in tlist if per_target[t] is not None]
        dom_avg[dom] = sum(rs)/len(rs) if rs else None
        print(f'domain {dom}: avg pearson = {"%.3f"%dom_avg[dom] if dom_avg[dom] is not None else "NA"}  ({rs})')
    macro = statistics.mean([v for v in dom_avg.values() if v is not None])
    print(f'=== MACRO PEARSON = {macro:.3f} ===')

if __name__ == '__main__':
    pairs = []
    for a in sys.argv[1:]:
        m, p = a.split('=', 1)
        pairs.append((m, p))
    main(pairs)
PYEOF
